package main

import (
	"fmt"
	"log"
	"net/http"
	"sync"
	"time"

	"github.com/gofiber/fiber/v2"
)

// WebhookRequest represents the expected JSON payload
type WebhookRequest struct {
	WebhookURL string `json:"webhook_url"`
}

// WebhookResponse represents the JSON response structure
type WebhookResponse struct {
	Success bool   `json:"success"`
	Message string `json:"message,omitempty"`
	Error   string `json:"error,omitempty"`
	URL     string `json:"url,omitempty"`
}

var (
	// In-memory storage to simulate saving the configuration
	savedWebhookURL string
	mu              sync.Mutex
)

// ConfigureWebhook handles the POST request to configure and validate a webhook
func ConfigureWebhook(ctx *fiber.Ctx) error {
	var reqBody WebhookRequest

	// Parse the JSON body
	if err := ctx.BodyParser(&reqBody); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(WebhookResponse{
			Success: false,
			Error:   "Invalid JSON body",
		})
	}

	// Validate presence of webhook_url
	if reqBody.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(WebhookResponse{
			Success: false,
			Error:   "webhook_url is required",
		})
	}

	// Create an HTTP client with a strict 3-second timeout for the test request
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Prepare the GET request
	req, err := http.NewRequest(http.MethodGet, reqBody.WebhookURL, nil)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(WebhookResponse{
			Success: false,
			Error:   fmt.Sprintf("Invalid URL format: %v", err),
		})
	}

	// Execute the test request
	resp, err := client.Do(req)
	if err != nil {
		return ctx.Status(fiber.StatusBadGateway).JSON(WebhookResponse{
			Success: false,
			Error:   fmt.Sprintf("Failed to reach webhook URL (timeout or network error): %v", err),
		})
	}
	defer resp.Body.Close()

	// Check if the webhook endpoint returned a successful status code (2xx or 3xx)
	if resp.StatusCode >= 400 {
		return ctx.Status(fiber.StatusBadGateway).JSON(WebhookResponse{
			Success: false,
			Error:   fmt.Sprintf("Webhook URL returned error status code: %d", resp.StatusCode),
		})
	}

	// Save the configuration
	mu.Lock()
	savedWebhookURL = reqBody.WebhookURL
	mu.Unlock()

	// Return success response
	return ctx.Status(fiber.StatusOK).JSON(WebhookResponse{
		Success: true,
		Message: "Webhook configured and validated successfully",
		URL:     reqBody.WebhookURL,
	})
}

func main() {
	app := fiber.New()

	// Register the POST route
	app.Post("/configure-webhook", ConfigureWebhook)

	// Start the Fiber server
	log.Println("Server is running on http://localhost:3000")
	log.Fatal(app.Listen(":3000"))
}

