	// Validate that webhook_url is provided
	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook_url is required",
		})
	}

	// Validate URL format
	parsedURL, err := url.ParseRequestURI(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid webhook URL format",
		})
	}

	// Ensure the URL has a valid scheme
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook URL must use http or https scheme",
		})
	}

	// Ensure the URL has a valid host
	if parsedURL.Host == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook URL must have a valid host",
		})
	}

	dialer := &net.Dialer{
		Timeout:   3 * time.Second,
		KeepAlive: 30 * time.Second,
	}

	// Custom transport to prevent SSRF attacks by validating resolved IPs
	transport := &http.Transport{
		DialContext: func(ctxDial context.Context, network, addr string) (net.Conn, error) {
			host, port, err := net.SplitHostPort(addr)
			if err != nil {
				return nil, err
			}

			ips, err := net.DefaultResolver.LookupIPAddr(ctxDial, host)
			if err != nil {
				return nil, err
			}

			var validIP net.IP
			for _, ip := range ips {
				if !isPrivateIP(ip.IP) {
					validIP = ip.IP
					break
				}
			}

			if validIP == nil {
				return nil, fmt.Errorf("access to private or internal IP addresses is forbidden")
			}

			// Dial the specific validated IP to prevent DNS rebinding / TOCTOU issues
			return dialer.DialContext(ctxDial, network, net.JoinHostPort(validIP.String(), port))
		},
	}

	// Create a custom HTTP client with timeout
	client := &http.Client{
		Timeout:   5 * time.Second,
		Transport: transport,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
