package main

import (
	"fmt"
	"net/http"
	"time"

	"github.com/gofiber/fiber/v2"
)

type ConfigureWebhookRequest struct {
	WebhookURL string `json:"webhook_url"`
}

type ConfigureWebhookResponse struct {
	Success bool   `json:"success"`
	Message string `json:"message"`
}

// Global variable to simulate saving the configuration
var currentWebhookURL string

func ConfigureWebhook(ctx *fiber.Ctx) error {
	var req ConfigureWebhookRequest
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(ConfigureWebhookResponse{
			Success: false,
			Message: "Invalid request body",
		})
	}

	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(ConfigureWebhookResponse{
			Success: false,
			Message: "webhook_url is required",
		})
	}

	// Validate the webhook URL by sending a test request using GET method
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	resp, err := client.Get(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(ConfigureWebhookResponse{
			Success: false,
			Message: fmt.Sprintf("Failed to reach webhook URL: %v", err),
		})
	}
	defer resp.Body.Close()

	// Check if the response status code indicates an error
	if resp.StatusCode >= 400 {
		return ctx.Status(fiber.StatusBadRequest).JSON(ConfigureWebhookResponse{
			Success: false,
			Message: fmt.Sprintf("Webhook URL returned error status: %d", resp.StatusCode),
		})
	}

	// Save the configuration
	currentWebhookURL = req.WebhookURL

	return ctx.Status(fiber.StatusOK).JSON(ConfigureWebhookResponse{
		Success: true,
		Message: "Webhook configured successfully",
	})
}

func main() {
	app := fiber.New()

	app.Post("/configure-webhook", ConfigureWebhook)

	app.Listen(":3000")
}

