	var req webhookRequest
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid JSON format",
		})
	}

	// Validate that webhook_url is provided
	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook_url is required",
		})
	}

	// Validate URL format
	parsedURL, err := url.ParseRequestURI(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid webhook URL format",
		})
	}

	// Ensure the URL has a valid scheme
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook URL must use http or https scheme",
		})
	}

	// Create a custom HTTP client with timeout and SSRF protection
	transport := &http.Transport{
		DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
			host, port, err := net.SplitHostPort(addr)
			if err != nil {
				return nil, err
			}

			// Resolve the hostname to IP addresses
			ips, err := net.DefaultResolver.LookupIPAddr(ctx, host)
			if err != nil {
				return nil, err
			}

			// Filter out private/internal IP addresses to prevent SSRF
			var publicIPs []net.IP
			for _, ip := range ips {
				if !isPrivateIP(ip.IP) {
					publicIPs = append(publicIPs, ip.IP)
				}
			}

			if len(publicIPs) == 0 {
				return nil, fmt.Errorf("no public IP addresses found for host")
			}

			dialer := &net.Dialer{
				Timeout: 3 * time.Second,
			}

			// Dial the resolved public IP directly to prevent DNS rebinding attacks
			var lastErr error
			for _, ip := range publicIPs {
				ipAddr := net.JoinHostPort(ip.String(), port)
				conn, err := dialer.DialContext(ctx, network, ipAddr)
				if err == nil {
					return conn, nil
				}
				lastErr = err
			}
