		Success: true,
		Message: "Webhook configured and saved successfully",
	})
}

func main() {
	app := fiber.New()

	// Register the POST route
	app.Post("/configure-webhook", ConfigureWebhook)

	// Start the server
	app.Listen(":3000")
}

