var savedWebhookURL string

// ConfigureWebhook handles the POST request to configure and validate a webhook URL
func ConfigureWebhook(ctx *fiber.Ctx) error {
	var req WebhookRequest

	// Parse the JSON body
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(WebhookResponse{
			Success: false,
			Error:   "Invalid JSON payload",
		})
	}

	// Validate that the webhook_url field is not empty
	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(WebhookResponse{
			Success: false,
			Error:   "webhook_url is required",
		})
	}

	// Create an HTTP client with a strict 3-second timeout for the test request
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Send a GET request to validate the webhook URL
	resp, err := client.Get(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(WebhookResponse{
			Success: false,
			Error:   fmt.Sprintf("Webhook validation failed: %v", err),
		})
	}
	defer resp.Body.Close()

	// Note: We only check for network/timeout errors (err != nil). 
	// Webhooks might legitimately return 4xx/5xx status codes (e.g., 401 Unauthorized, 405 Method Not Allowed) 
	// when receiving a plain GET request, but the endpoint is still considered reachable and valid.

	// Save the configuration
	savedWebhookURL = req.WebhookURL

	// Return success response
	return ctx.Status(fiber.StatusOK).JSON(WebhookResponse{
		Success:    true,
		Message:    "Webhook configured and validated successfully",
		WebhookURL: savedWebhookURL,
		StatusCode: resp.StatusCode,
	})
}

