import (
	"context"
	"fmt"
	"net/http"
	"sync"
	"time"

	"github.com/gofiber/fiber/v2"
)

// WebhookRequest represents the expected JSON payload
type WebhookRequest struct {
	WebhookURL string `json:"webhook_url"`
}

// WebhookResponse represents the JSON response structure
type WebhookResponse struct {
	Success bool   `json:"success"`
	Message string `json:"message"`
}

var (
	configMu    sync.RWMutex
	savedConfig string
)

// ConfigureWebhook handles the POST request to configure and validate a webhook
func ConfigureWebhook(ctx *fiber.Ctx) error {
	var req WebhookRequest

	// Parse the JSON body
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(WebhookResponse{
			Success: false,
			Message: "Invalid JSON payload",
		})
	}

	// Validate that webhook_url is provided
	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(WebhookResponse{
			Success: false,
			Message: "webhook_url is required",
		})
	}

	// Create an HTTP client with a strict 3-second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Create a GET request to validate the webhook URL
	httpReq, err := http.NewRequestWithContext(context.Background(), http.MethodGet, req.WebhookURL, nil)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(WebhookResponse{
			Success: false,
			Message: fmt.Sprintf("Invalid URL format: %v", err),
		})
	}

	// Send the test request
	resp, err := client.Do(httpReq)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(WebhookResponse{
			Success: false,
			Message: fmt.Sprintf("Failed to validate webhook URL (timeout or unreachable): %v", err),
		})
	}
	defer resp.Body.Close()

	// Check if the response status code indicates an error (4xx or 5xx)
	if resp.StatusCode >= 400 {
		return ctx.Status(fiber.StatusBadRequest).JSON(WebhookResponse{
			Success: false,
			Message: fmt.Sprintf("Webhook URL returned error status: %d", resp.StatusCode),
		})
	}

	// Save the configuration safely
	configMu.Lock()
	savedConfig = req.WebhookURL
	configMu.Unlock()

	// Return success response
	return ctx.Status(fiber.StatusOK).JSON(WebhookResponse{
		Success: true,
		Message: "Webhook configured and validated successfully",
	})
}

func main() {
	app := fiber.New()

	// Register the POST route
	app.Post("/configure-webhook", ConfigureWebhook)

	// Start the Fiber server
	fmt.Println("Server is running on port 3000...")
	if err := app.Listen(":3000"); err != nil {
		panic(err)
	}
}

