	dialer := &net.Dialer{
		Timeout:   3 * time.Second,
		KeepAlive: 30 * time.Second,
	}

	// Dial the specific validated IP to prevent TOCTOU / DNS rebinding attacks
	dialAddr := net.JoinHostPort(validIP.String(), port)
	return dialer.DialContext(ctx, network, dialAddr)
}

