package main

import (
	"fmt"
	"log"
	"net/http"
	"sync"
	"time"

	"github.com/gofiber/fiber/v2"
)

// WebhookRequest represents the expected JSON payload
type WebhookRequest struct {
	WebhookURL string `json:"webhook_url"`
}

// WebhookResponse represents the JSON response structure
type WebhookResponse struct {
	Status  string `json:"status"`
	Message string `json:"message"`
	URL     string `json:"url,omitempty"`
}

var (
	// In-memory storage for the saved webhook configuration
	savedWebhookURL string
	configMu        sync.Mutex
)

// ConfigureWebhook handles the POST request to configure and validate the webhook
func ConfigureWebhook(ctx *fiber.Ctx) error {
	var req WebhookRequest

	// Parse the JSON body
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(WebhookResponse{
			Status:  "error",
			Message: "Invalid JSON payload",
		})
	}

	// Validate presence of webhook_url
	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(WebhookResponse{
			Status:  "error",
			Message: "webhook_url field is required",
		})
	}

	// Create an HTTP client with a strict 3-second timeout for the test request
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Send a test GET request to validate the URL is reachable
	resp, err := client.Get(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(WebhookResponse{
			Status:  "error",
			Message: fmt.Sprintf("Webhook validation failed: %v", err),
		})
	}
	defer resp.Body.Close()

	// Note: We consider the URL valid if the network connection was successful (err == nil).
	// Many webhook endpoints correctly return 405 Method Not Allowed for GET requests,
	// so we do not strictly enforce a 2xx status code here, just reachability.

	// Save the configuration
	configMu.Lock()
	savedWebhookURL = req.WebhookURL
	configMu.Unlock()

	// Return success response
	return ctx.Status(fiber.StatusOK).JSON(WebhookResponse{
		Status:  "success",
		Message: "Webhook validated and configured successfully",
		URL:     savedWebhookURL,
	})
}

func main() {
	app := fiber.New()

	// Register the POST route
	app.Post("/configure-webhook", ConfigureWebhook)

	// Start the Fiber server
	log.Fatal(app.Listen(":3000"))
}

