package main

import (
	"fmt"
	"net/http"
	"sync"
	"time"

	"github.com/gofiber/fiber/v2"
)

// WebhookRequest represents the expected JSON payload
type WebhookRequest struct {
	WebhookURL string `json:"webhook_url"`
}

// APIResponse represents the standard JSON response structure
type APIResponse struct {
	Success bool   `json:"success"`
	Message string `json:"message"`
}

// configStore acts as a simple in-memory database to save the configuration
var configStore struct {
	mu  sync.RWMutex
	url string
}

// ConfigureWebhook handles the POST request to validate and save the webhook URL
func ConfigureWebhook(ctx *fiber.Ctx) error {
	var req WebhookRequest

	// Parse the JSON body
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(APIResponse{
			Success: false,
			Message: "Invalid JSON body",
		})
	}

	// Validate that the webhook_url field is present
	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(APIResponse{
			Success: false,
			Message: "webhook_url is required",
		})
	}

	// Create an HTTP client with a strict 3-second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Prepare the GET request to test the webhook URL
	httpReq, err := http.NewRequest(http.MethodGet, req.WebhookURL, nil)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(APIResponse{
			Success: false,
			Message: fmt.Sprintf("Invalid URL format: %v", err),
		})
	}

	// Execute the test request
	resp, err := client.Do(httpReq)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(APIResponse{
			Success: false,
			Message: fmt.Sprintf("Failed to reach webhook URL (timeout or network error): %v", err),
		})
	}
	defer resp.Body.Close()

	// Consider any 2xx status code as a successful validation
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadRequest).JSON(APIResponse{
			Success: false,
			Message: fmt.Sprintf("Webhook URL validation failed with HTTP status: %d", resp.StatusCode),
		})
	}

	// Save the configuration to our in-memory store
	configStore.mu.Lock()
	configStore.url = req.WebhookURL
	configStore.mu.Unlock()

	// Return success response
	return ctx.Status(fiber.StatusOK).JSON(APIResponse{
		Success: true,
		Message: "Webhook configured and validated successfully",
	})
}

func main() {
	app := fiber.New()

	// Register the POST route
	app.Post("/configure-webhook", ConfigureWebhook)

	// Start the Fiber server
	fmt.Println("Server is running on http://localhost:3000")
	if err := app.Listen(":3000"); err != nil {
		fmt.Printf("Error starting server: %v\n", err)
	}
}

