package main

import (
	"fmt"
	"net/http"
	"sync"
	"time"

	"github.com/gofiber/fiber/v2"
)

// WebhookPayload represents the expected JSON request body
type WebhookPayload struct {
	WebhookURL string `json:"webhook_url"`
}

// APIResponse represents the JSON response structure
type APIResponse struct {
	Success bool   `json:"success"`
	Message string `json:"message"`
	URL     string `json:"url,omitempty"`
}

var (
	// In-memory storage to simulate saving the configuration
	configuredURL string
	mu            sync.RWMutex
)

// ConfigureWebhook handles the POST request to configure and validate a webhook
func ConfigureWebhook(ctx *fiber.Ctx) error {
	var payload WebhookPayload

	// Parse the JSON body
	if err := ctx.BodyParser(&payload); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(APIResponse{
			Success: false,
			Message: "Invalid JSON payload",
		})
	}

	// Validate that the webhook_url is provided
	if payload.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(APIResponse{
			Success: false,
			Message: "webhook_url is required",
		})
	}

	// Create an HTTP client with a strict 3-second timeout for the test request
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Send a test GET request to validate the webhook URL
	resp, err := client.Get(payload.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(APIResponse{
			Success: false,
			Message: fmt.Sprintf("Webhook validation failed: %v", err),
		})
	}
	defer resp.Body.Close()

	// Consider any 4xx or 5xx status code as a validation failure
	if resp.StatusCode >= 400 {
		return ctx.Status(fiber.StatusBadRequest).JSON(APIResponse{
			Success: false,
			Message: fmt.Sprintf("Webhook URL returned an error status code: %d", resp.StatusCode),
		})
	}

	// Save the configuration (simulated via thread-safe in-memory variable)
	mu.Lock()
	configuredURL = payload.WebhookURL
	mu.Unlock()

	// Return success response
	return ctx.Status(fiber.StatusOK).JSON(APIResponse{
		Success: true,
		Message: "Webhook validated and configured successfully",
		URL:     configuredURL,
	})
}

func main() {
	app := fiber.New()

	// Register the POST route
	app.Post("/configure-webhook", ConfigureWebhook)

	// Start the Fiber server
	fmt.Println("Server is running on http://localhost:3000")
	if err := app.Listen(":3000"); err != nil {
		fmt.Printf("Failed to start server: %v\n", err)
	}
}

